effect.shader:
float gmRing(float d,float r,float w){return exp(-abs(d-r)/max(w,0.0001));}
void main(){
vec2 uv=acScreenNorm, aspect=vec2(acScreenSize.x/max(acScreenSize.y,1.0),1.0); vec2 p=(uv-lightPosition)*aspect;
float d=length(p); float core=0.004/max(d*d,0.0008); float halo=gmRing(d,haloSize,haloSize*0.16)*0.28;
float streakMask=exp(-abs(p.y)/(0.003+0.018*(1.0-streak)))*exp(-abs(p.x)*1.7)*streak;
vec3 flare=(core+halo+streakMask)*flareColor.rgb; vec2 axis=(vec2(0.5)-lightPosition)*aspect;
for(int i=0;i<10;i++){
float enabled=step(float(i)+0.5,ghostCount); float fi=float(i)+1.0; vec2 center=axis*(fi/(ghostCount+1.0))*1.8;
float gd=length((uv-vec2(0.5))*aspect-center); float disk=1.0-smoothstep(ghostSize*(0.45+fi*0.08),ghostSize*(0.65+fi*0.08),gd);
vec3 spectral=0.55+0.45*cos(vec3(0.0,2.1,4.2)+fi*dispersion); flare+=disk*spectral*flareColor.rgb*enabled/(1.0+fi*0.35);
}
flare*=brightness; vec4 src=texture2DCv(inputImg.texture,uv); vec3 screen=1.0-(1.0-src.rgb)*(1.0-clamp(flare,0.0,1.0));
gl_FragColor=vec4(mix(src.rgb,screen,mixAmount),src.a+clamp(max(max(flare.r,flare.g),flare.b),0.0,1.0)*mixAmount*(1.0-src.a));
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
